    g.shadowColor = flash ? 'transparent' : col; g.shadowBlur = 5; g.textBaseline = 'alphabetic';
    g.fillStyle = ink; g.font = '700 11px ui-monospace, Menlo, monospace'; g.textAlign = 'left'; g.fillText('点検', 50, 22);
    g.font = '800 12px ui-monospace, Menlo, monospace'; g.textAlign = 'right'; if (all || calm || f % 6 < 4) g.fillText(all ? 'READY' : 'HOLD', 208, 22);
    g.fillStyle = soft; g.fillRect(12, 27, 196, 1);
